package com.exl.interview.api;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PostConstruct;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.ClassPathResource;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import java.util.*;

@Service
public class TemplateCatalogue {
 public record Criterion(String id,String label,int maxPoints,String guidance){}
 public record TestCase(String id,String input,String expected){}
 public record Item(String id,String kind,String text,List<String> choices,String correctAnswer,String explanation,int maxPoints,List<Criterion> rubric,String starterCode,List<TestCase> publicTests,List<TestCase> hiddenTests,String referenceSolution){}
 public record Definition(String version,String title,String description,int durationMinutes,List<String> skills,String reviewerInstructions,List<Item> items){}
 public record Summary(String version,String title,String description,int durationMinutes,List<String> skills,int questionCount,String status,boolean runnerEnabled,String role,Long updatedAt){}
 public record Page(List<Summary> items,int page,int size,long total,int totalPages,long allCount,long pendingCount,long approvedCount,long retiredCount,boolean enabled){}
 private final JdbcTemplate db;private final ObjectMapper json;private final boolean enabled;private final JavaCodeRunner runner;
 public TemplateCatalogue(JdbcTemplate db,ObjectMapper json,JavaCodeRunner runner,@Value("${interview.catalogue-enabled:false}") boolean enabled){this.db=db;this.json=json;this.runner=runner;this.enabled=enabled;}
 public boolean enabled(){return enabled;}
 public void requireEnabled(){if(!enabled)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Start the Java template preview profile to use this feature");}
 @PostConstruct public void seed()throws Exception{if(!enabled)return;String content;try(var input=new ClassPathResource("java-backend-v1.json").getInputStream()){content=new String(input.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}Definition d=json.readValue(content,Definition.class);if(db.queryForObject("SELECT COUNT(*) FROM assessment_templates WHERE version=?",Integer.class,d.version())==0)db.update("INSERT INTO assessment_templates (version,status,definition,updated_at) VALUES (?,'DRAFT',?,?)",d.version(),content,System.currentTimeMillis());
  for(String version:db.queryForList("SELECT version FROM assessment_templates WHERE title IS NULL OR description IS NULL",String.class)){Definition definition=definition(version);String title=definition.title().replace("Developer ? Mid-level","Developer - Mid-level");db.update("UPDATE assessment_templates SET title=?,role_name=?,skills=?,duration_minutes=?,question_count=?,description=?,updated_at=COALESCE(updated_at,approved_at) WHERE version=?",title,title.split(" - ")[0],json.writeValueAsString(definition.skills()),definition.durationMinutes(),definition.items().size(),definition.description(),version);}}
 public Definition definition(String version){requireEnabled();var rows=db.queryForList("SELECT definition FROM assessment_templates WHERE version=?",String.class,version);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Template not found");try{return json.readValue(rows.getFirst(),Definition.class);}catch(Exception e){throw new IllegalStateException(e);}}
 public List<Summary> summaries(){requireEnabled();return db.query("SELECT version,status FROM assessment_templates ORDER BY version",(r,n)->{var d=definition(r.getString(1));return new Summary(d.version(),d.title(),d.description(),d.durationMinutes(),d.skills(),d.items().size(),r.getString(2),runner.enabled(),d.title().split(" - ")[0],null);});}
 public Page page(int page,int size,String search,String status,String sort){
  if(page<0||!Set.of(10,25,50).contains(size)||search.length()>200||!Set.of("ALL","DRAFT","IN_REVIEW","APPROVED","RETIRED","PENDING").contains(status)||!Set.of("UPDATED","TITLE","VERSION").contains(sort))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid template queue filters");
  if(!enabled)return new Page(List.of(),0,size,0,1,0,0,0,0,false);
  var args=new ArrayList<Object>();String where=" WHERE 1=1";if(!search.isBlank()){String pattern="%"+search.trim().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%";where+=" AND (LOWER(title) LIKE ? ESCAPE '!' OR LOWER(role_name) LIKE ? ESCAPE '!' OR LOWER(skills) LIKE ? ESCAPE '!' OR LOWER(version) LIKE ? ESCAPE '!')";for(int i=0;i<4;i++)args.add(pattern);}
  var counts=db.queryForMap("SELECT COUNT(*) AS total,COALESCE(SUM(CASE WHEN status IN ('DRAFT','IN_REVIEW') THEN 1 ELSE 0 END),0) AS pending,COALESCE(SUM(CASE WHEN status='APPROVED' THEN 1 ELSE 0 END),0) AS approved,COALESCE(SUM(CASE WHEN status='RETIRED' THEN 1 ELSE 0 END),0) AS retired FROM assessment_templates"+where,args.toArray());
  long all=((Number)counts.get("total")).longValue(),pending=((Number)counts.get("pending")).longValue(),approved=((Number)counts.get("approved")).longValue(),retired=((Number)counts.get("retired")).longValue();
  if(status.equals("PENDING"))where+=" AND status IN ('DRAFT','IN_REVIEW')";else if(!status.equals("ALL")){where+=" AND status=?";args.add(status);}
  long total=db.queryForObject("SELECT COUNT(*) FROM assessment_templates"+where,Long.class,args.toArray());int pages=(int)Math.max(1,Math.min(Integer.MAX_VALUE,(total+size-1)/size)),current=Math.min(page,pages-1);args.add(size);args.add((long)current*size);
  String order=sort.equals("TITLE")?"title ASC,version ASC":sort.equals("VERSION")?"version ASC":"updated_at DESC NULLS LAST,version ASC";
  var items=db.query("SELECT version,title,role_name,skills,duration_minutes,question_count,status,updated_at,description FROM assessment_templates"+where+" ORDER BY "+order+" LIMIT ? OFFSET ?",(r,n)->{try{return new Summary(r.getString("version"),r.getString("title"),r.getString("description"),r.getInt("duration_minutes"),json.readValue(r.getString("skills"),new com.fasterxml.jackson.core.type.TypeReference<List<String>>(){}),r.getInt("question_count"),r.getString("status"),runner.enabled(),r.getString("role_name"),(Long)r.getObject("updated_at"));}catch(Exception e){throw new IllegalStateException(e);}},args.toArray());
  return new Page(items,current,size,total,pages,all,pending,approved,retired,true);
 }
 public String versionForSession(String id){if(!enabled)return null;var rows=db.queryForList("SELECT j.template_version FROM sessions s JOIN interviews j ON j.id=s.interview_id WHERE s.id=?",String.class,id);return rows.isEmpty()?null:rows.getFirst();}
 public Item item(String version,String question){return definition(version).items().stream().filter(q->q.id().equals(question)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Question not part of this template"));}
 public List<SessionController.Question> publicQuestions(String version){return definition(version).items().stream().map(q->new SessionController.Question(q.id(),q.kind(),q.text(),q.choices())).toList();}
 public void approve(String version,String reviewer){var d=definition(version);String status=db.queryForObject("SELECT status FROM assessment_templates WHERE version=?",String.class,version);if("RETIRED".equals(status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Retired versions cannot be approved");if("APPROVED".equals(status))return;if(d.items().stream().mapToInt(Item::maxPoints).sum()!=100)throw new IllegalStateException("Template weights must total 100");for(var q:d.items()){if(q.kind().equals("MCQ")&&!q.choices().contains(q.correctAnswer()))throw new IllegalStateException("Invalid answer key");if(q.kind().equals("CODING")){var tests=new ArrayList<>(q.publicTests());tests.addAll(q.hiddenTests());var result=runner.run(q.referenceSolution(),tests);if(!result.state().equals("COMPLETE")||result.passed()!=tests.size())throw new ResponseStatusException(HttpStatus.CONFLICT,"Reference solution validation failed: "+result.state()+". Configure Docker and validate again.");}}db.update("UPDATE assessment_templates SET status='APPROVED',approved_by=?,approved_at=?,updated_at=? WHERE version=?",reviewer,System.currentTimeMillis(),System.currentTimeMillis(),version);}
 public String createInterview(String owner,String version,String title,Long scheduledAt){return createInterview(owner,version,title,scheduledAt,null);}
 public String createInterview(String owner,String version,String title,Long scheduledAt,String description){if(description!=null&&description.length()>4000)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Assessment brief exceeds 4000 characters");var d=definition(version);if(!"APPROVED".equals(db.queryForObject("SELECT status FROM assessment_templates WHERE version=?",String.class,version)))throw new ResponseStatusException(HttpStatus.CONFLICT,"A technical reviewer must validate and approve this template first");if(scheduledAt==null||scheduledAt<0||title==null||title.isBlank()||title.length()>200)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Title and schedule are required");String id=UUID.randomUUID().toString();try{db.update("INSERT INTO interviews (id,recruiter_id,title,description,duration_seconds,scheduled_at,questions,created_at,template_version) VALUES (?,?,?,?,?,?,?,?,?)",id,owner,title.trim(),description==null?d.description():description.trim(),d.durationMinutes()*60,scheduledAt,json.writeValueAsString(publicQuestions(version)),System.currentTimeMillis(),version);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}return id;}
}
